import{_ as o,o as a,c as s,ag as r}from"./chunks/framework.BjY7aUvS.js";const _=JSON.parse('{"title":"社保公积金域启动：家庭财务安全 tips 进入收录范围","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0016-social-domain.md","filePath":"project/adr/0016-social-domain.md"}'),e={name:"project/adr/0016-social-domain.md"};function i(n,t,c,l,p,d){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="社保公积金域启动-家庭财务安全-tips-进入收录范围" tabindex="-1">社保公积金域启动：家庭财务安全 tips 进入收录范围 <a class="header-anchor" href="#社保公积金域启动-家庭财务安全-tips-进入收录范围" aria-label="Permalink to &quot;社保公积金域启动：家庭财务安全 tips 进入收录范围&quot;">​</a></h1><p>ADR 0015 曾将&quot;个人政务类（社保/公积金）&quot;列为暂缓——用户随后点名纠正：养老金身故权益（个人账户继承、计发月数、丧葬补助金/抚恤金）正是家庭最需要且最少人讲的 tips。据此启动<strong>社保公积金域</strong>（目录 <code>/social/</code>，语料类型 <code>social</code>），首批三篇：</p><ul><li><strong>[词条] 养老金身故后怎么办</strong>：继承与遗属待遇的政策科普（社会保险法第十四条、人社部发〔2021〕56号遗属待遇、计发月数 139、公积金继承），按&quot;城乡居民/城镇职工&quot;两条线分开写。</li><li><strong>[查询页] 国家社会保险公共服务平台</strong>（si.12333.gov.cn，已浏览器核验可达）：权益记录、养老金测算（含城乡居民版）、待遇资格认证。</li><li><strong>[查询页] 公积金查询</strong>：余额、依法提取情形、继承提取、12329。</li></ul><p>事实核查记录：用户口述&quot;139 个月打齐缴费的部分&quot;已锐化为<strong>计发月数</strong>概念（60 岁→139，是除数不是年限上限；领不满身故则个人账户剩余依法继承；基础养老金发到身故当月、不可继承），写入词条并纠正三个常见误区（含&quot;冒领须退还、先申报后领遗属待遇&quot;）。</p><p>口径纪律：法律与部委文件逐条标注出处；<strong>地方差异如实写&quot;各地不同&quot;</strong>；凭记忆转述的文号与月数全部标&quot;待核验&quot;，进入校验看板流程。同时修复发现的历史 bug：export-rss 与检索页 pathOf 漏了 query 分支（查询页链接被错误指向 /standards/），本次补上 query 与 social 两个分支。</p>',5)])])}const g=o(e,[["render",i]]);export{_ as __pageData,g as default};
